import { createRef, Component } from 'react'
import { connect } from 'react-redux'
import { Container, CustomText, InnerForm, Button } from '../../../../../components'
import { LANG_STRINGS } from '../../../../../lang'
import StepsHeader from '../../../../../components/StepsHeader'
import { MotorProtectionFormStyle } from './index.style'
import { Row, BottomActionContainerStyle } from '../../../../../commonStyle/index.style'
import { AgentColorPallette } from '../../../../../configs/colorPallete'
import CustomCheckbox from '../../../../../components/CustomCheckbox'
import { getMotorInsuranceForm, getMotorCustomerFormData } from '../constants'
import { NotificationManager, NotificationContainer } from 'react-notifications'
import motorActions from '../../../../../redux/motor/actions'
import { getYearRangeForGiveNumber, getParamsFromUri, getQueryParams } from '../../../../../helpers/utility'
import { STNK_MOTOR_CYCLE } from '../../../../../images'
import ImageGuideModal from '../../../../../components/PolicyCustAgentForm/components/ImageGuideModal'
import SingleImgContainer from '../../../../../components/SingleImgContainer'
import customerActions from '../../../../../redux/customer/actions'
import { getDobFmt, prefixCountryCode } from '../../../../../helpers/getPackageBody'
import { ADIRA_BIKE_PROTECTION_LITE } from '../../../../../constants/pkgCode'
import isEmpty from 'lodash/isEmpty'
import { getFromLocalStorageData, setToLocalStorage } from '../../../../../helpers/localstorage'
import { POLICY_DATA_KEY, POLICY_PKG_DATA } from '../../../../../constants/cookies'
import find from 'lodash/find'
import TermsNConditionModal from '../../../../Private/Application/components/TermsNConditionModal'

const { createCustomerPolicy, updateCustomerPolicyData, resetCustomerStore } = customerActions
const { getMotorBrandRequest, getMotorModelRequest, resetMotorStore } = motorActions
class MotorProtectionForm extends Component {
  constructor (props) {
    super(props)
    this.state = {
      isTermsChecked: false,
      showTermsModal: false,
      showImgModal: false
    }
    this.policyData = {}
    this.finalData = getFromLocalStorageData(POLICY_DATA_KEY) || {}
    this.pkgDetails = getFromLocalStorageData(POLICY_PKG_DATA) || {}
    this.prePolicyId = !isEmpty(this.finalData) && this.finalData.token
    this.child = createRef()
    this.customerData = createRef()
  }

  componentDidMount () {
    this.props.getMotorBrandRequest()
    if (!isEmpty(this.finalData)) {
      // getting the model list to prefilled the data
      this.props.getMotorModelRequest({
        parent_id: this.finalData.brand // this value used if user comes back on this page
      })
    }
  }

  componentWillReceiveProps (nextProps) {
    const {
      creatCustomerPolicyStatus, customerPolicy, resetCustomerStore,
      updateCustomerPolicyStatus, upadtePolicyError
    } = nextProps
    if (creatCustomerPolicyStatus === 'success') {
      // after successful, calling the update api so that backend
      this.prePolicyId = customerPolicy.id
      this.updatePolicyData()
      resetCustomerStore(['creatCustomerPolicyStatus'])
    }

    if (updateCustomerPolicyStatus === 'success') {
      // after update the policy content move the customer to policy details
      const productCode = getParamsFromUri.call(this, 'productCode')
      this.props.history.push({
        pathname: `/customer/${productCode}/summary/${customerPolicy.id}`
      })
      resetCustomerStore(['updateCustomerPolicyStatus'])
    } else if (updateCustomerPolicyStatus && upadtePolicyError) {
      NotificationManager.error(updateCustomerPolicyStatus)
      resetCustomerStore(['updateCustomerPolicyStatus'])
    }
  }

  updatePolicyData = () => {
    // update the policy of the user
    const updatedForm = {
      ...this.finalData,
      token: this.prePolicyId
    }
    setToLocalStorage(POLICY_DATA_KEY, updatedForm)
    this.props.updateCustomerPolicyData(updatedForm)
  }

  handleCreatePolicy = async (e) => {
    // this get the response from the innerForm and handle submit function is defined
    // inside the innerForm function
    const response1 = await this.child.current.handleSubmit(e)
    const response2 = await this.customerData.current.handleSubmit(e)
    if (!isEmpty(response1) && !isEmpty(response2)) {
      const { motorModelList, motorBrandList } = this.props
      this.finalData = {
        customer_data: {
          name: response2.name,
          email: response2.email,
          mobile_no: `${response2.mobile_no}`.startsWith('0') ? prefixCountryCode(response2.mobile_no) : `62-${response2.mobile_no}`
        },
        dob: getDobFmt(response2.dob),
        model: response1.model,
        model_name: find(motorModelList, { id: response1.model }).display_name,
        brand: response1.brand,
        brand_name: find(motorBrandList, { id: response1.brand }).display_name,
        chasis_number: response1.chasis_number,
        year: response1.year,
        agent_ref: getParamsFromUri.call(this, 'agentRef'),
        code: ADIRA_BIKE_PROTECTION_LITE,
        premium: {
          period: 12
        }
      }
      if (this.prePolicyId) {
        // if this is the update call then call the update api
        this.updatePolicyData()
      } else {
        this.props.createCustomerPolicy({
          ...this.finalData,
          leads_id: getQueryParams('tid') || ''
        })
      }
    }
  }

  handleToggleTermsModal = () => {
    this.setState((prevState) => ({
      showTermsModal: !prevState.showTermsModal
    }))
  }

  handleCloseImgModal = () => {
    this.setState({
      showImgModal: false
    })
  }

  handleSelectChange = (value) => {
    if (value.brand) {
      this.policyData.brand = value.brand
      this.props.getMotorModelRequest({
        parent_id: value.brand
      })
    } else if (value.model) {
      this.policyData.model = value.model
    }
  }

  handleOpenImgModal = () => {
    const imgContainer = (
      <SingleImgContainer
        title={LANG_STRINGS.stnkPhoto}
        imgUrl={STNK_MOTOR_CYCLE}
        titlePosition='up'
        titleAlign='start'
      />
    )
    this.setState((prevState) => ({
      showImgModal: !prevState.showImgModal,
      modalImgContainer: imgContainer,
      modalTitle: `${LANG_STRINGS.chassisNumber} (VIN)`,
      modalBottomTitle: LANG_STRINGS.motorCycleChassisNumberFound
    }))
  }

  getHeadingContainer = (title, error, bottom) => {
    return (
      <>
        <Row justify='space-between' align='center'>
          <CustomText color={AgentColorPallette.black} size='16px' weight={800} bottom={bottom}>
            {title}
          </CustomText>
          {
            error &&
              <CustomText color={AgentColorPallette.errorDark}>
                {'Wajib Diisi'}
              </CustomText>
          }
        </Row>
      </>
    )
  }

  handleTermsCheckBox = (useCase) => {
    this.setState({
      isTermsChecked: useCase,
      showTermsModal: false
    })
  }

  render () {
    const {
      isTermsChecked, showImgModal, modalTitle,
      modalImgContainer, modalBottomTitle, showTermsModal
    } = this.state
    const {
      motorBrandListLoader, motorModelListLoader, motorModelList,
      motorBrandList, createPolicyLoader, updatePolicyLoader
    } = this.props
    const modifyPolicyFormData = getMotorInsuranceForm({
      brandList: motorBrandList,
      modelList: motorModelList,
      year: getYearRangeForGiveNumber(new Date().getFullYear() - 8) // include of 8 years means 7 year age of the motor cycle
    }, this.finalData)
    const customerFormData = getMotorCustomerFormData(this.finalData)

    return (
      <Container
        title={LANG_STRINGS.motorCycleInsurance}
        loader={motorBrandListLoader || createPolicyLoader || updatePolicyLoader}
        showInnerHeader
        hideBottomTabs
      >
        <MotorProtectionFormStyle>
          <StepsHeader
            className='steps-header-custom'
            leftText={LANG_STRINGS.contentsData}
            current={2}
            totalSteps={4}
          />
          <div className='motor-form-content'>
            {
              this.getHeadingContainer(LANG_STRINGS.vehicleData, false, '14px')
            }
            <InnerForm
              formData={modifyPolicyFormData}
              onChangeSelect={this.handleSelectChange}
              onGuideClick={this.handleOpenImgModal}
              ref={this.child}
              loading={(motorModelListLoader && 'model')}
            />
            <div className='customer-data'>
              {
                this.getHeadingContainer(LANG_STRINGS.customerData, false, '14px')
              }
              <InnerForm
                formData={customerFormData}
                ref={this.customerData}
              />
            </div>
          </div>
          <BottomActionContainerStyle className='motor-form-terms-container' justify='start' align='start' padding='0'>
            <Row
              align='center' className='motor-form-terms'
              onClick={this.handleToggleTermsModal}
            >
              <CustomCheckbox
                isChecked={isTermsChecked}
                onChange={() => {}}
                name='motorTerms'
                id='motorTerms'
              />
              <CustomText
                color={AgentColorPallette.black}
                dangerouslySetInnerHTML={{
                  __html: LANG_STRINGS.agreeWithTermsConditions
                }}
              />
            </Row>
          </BottomActionContainerStyle>
          <BottomActionContainerStyle justify='start' align='start' padding='0'>
            <Row align='center' className='motor-form-submit'>
              <Button onClick={this.handleCreatePolicy} disabled={!isTermsChecked}>
                {LANG_STRINGS.next}
              </Button>
            </Row>
          </BottomActionContainerStyle>
        </MotorProtectionFormStyle>
        <ImageGuideModal
          showImgModal={showImgModal}
          title={modalTitle}
          onClose={this.handleCloseImgModal}
          modalImgContainer={modalImgContainer}
          bottomTitle={modalBottomTitle}
        />
        {
          showTermsModal && (
            <TermsNConditionModal
              isOpen={showTermsModal}
              tncData={this.pkgDetails.tnc.data}
              onAccept={() => this.handleTermsCheckBox(true)}
              onReject={() => this.handleTermsCheckBox(false)}
            />
          )
        }
        <NotificationContainer />
      </Container>
    )
  }
}

export default connect(
  (state) => ({
    packageDetail: state.Policy.packageDetail,
    motorBrandList: state.Motor.motorBrandList,
    motorBrandListStatus: state.Motor.motorBrandListStatus,
    motorModelList: state.Motor.motorModelList,
    motorModelListStatus: state.Motor.motorModelListStatus,
    customerPolicy: state.Customer.creatCustomerPolicy,
    creatCustomerPolicyStatus: state.Customer.creatCustomerPolicyStatus,
    updateCustomerPolicyData: state.Customer.updateCustomerPolicyData,
    updateCustomerPolicyStatus: state.Customer.updateCustomerPolicyStatus,

    motorBrandListLoader: state.Loading.GET_MOTOR_BRAND,
    motorModelListLoader: state.Loading.GET_MOTOR_MODEL,
    createPolicyLoader: state.Loading.CUSTOMER_POLICY,
    updatePolicyLoader: state.Loading.UPDATE_CUSTOMER_POLICY,
    upadtePolicyError: state.Error.UPDATE_CUSTOMER_POLICY
  }),
  {
    getMotorBrandRequest,
    getMotorModelRequest,
    createCustomerPolicy,
    updateCustomerPolicyData,
    resetMotorStore,
    resetCustomerStore
  }
)(MotorProtectionForm)
