import { LANG_STRINGS, ERROR_LANG } from '../../../../../lang'
import { get } from 'lodash'
import { getDobInCalendarView } from '../../../../../helpers/getPackageBody'

export const getMotorInsuranceForm = (data = {}, policy = {}) => {
  return {
    fields: [
      {
        type: 'select',
        placeholder: LANG_STRINGS.selectOfYearOfManufacturing,
        name: 'year',
        data: get(data, 'year', []),
        label: LANG_STRINGS.yearOfVehicleManufacturing,
        dataKey: 'year',
        displayKey: 'year',
        defaultValue: policy.year
      },
      {
        type: 'autosuggest',
        placeholder: LANG_STRINGS.searchForVehicleBrand,
        name: 'brand',
        data: get(data, 'brandList', []),
        label: LANG_STRINGS.vehicleBrands,
        dataKey: 'id',
        displayKey: 'display_name',
        defaultValue: policy.brand
      },
      {
        type: 'autosuggest',
        placeholder: LANG_STRINGS.serviceVehicleModelSeries,
        name: 'model',
        data: get(data, 'modelList', []),
        label: LANG_STRINGS.vehicleModalAndSeries,
        dataKey: 'id',
        displayKey: 'display_name',
        defaultValue: policy.model
      },
      {
        type: 'chasis_number',
        placeholder: `${LANG_STRINGS.enterMotorOrderNo}`,
        name: 'chasis_number',
        error: 'Masukkan nomor rangka 8 sampai 20 karakter',
        defaultValue: policy.chasis_number,
        guide: true,
        label: `${LANG_STRINGS.chassisNumber} (VIN)`
      }
    ]
  }
}

export const getMotorCustomerFormData = (data = {}) => {
  let mobile = get(data, 'customer_data.mobile_no', '')
  if (mobile && mobile.includes('62-')) {
    mobile = mobile.substring(3, mobile.length)
  }
  return {
    fields: [
      {
        type: 'name',
        label: LANG_STRINGS.fullName,
        placeholder: LANG_STRINGS.enterFullName,
        defaultValue: get(data, 'customer_data.name', ''),
        name: 'name'
      },
      {
        type: 'dob',
        label: LANG_STRINGS.dateOfBirth,
        placeholder: 'DD/MM/YYYY (contoh: 17/08/1945)',
        defaultValue: getDobInCalendarView(get(data, 'dob', '')),
        border: false,
        min: 17,
        max: 60,
        minType: 'year',
        error: ERROR_LANG.motorCycleHolderAgeError,
        name: 'dob'
      },
      {
        type: 'number',
        label: LANG_STRINGS.customerPhone,
        placeholder: LANG_STRINGS.enterPhoneNumber,
        defaultValue: mobile,
        name: 'mobile_no'
      },
      {
        type: 'email',
        label: LANG_STRINGS.emailAddress,
        placeholder: LANG_STRINGS.enterEmailAddress,
        defaultValue: get(data, 'customer_data.email', ''),
        name: 'email'
      }
    ]
  }
}

